  {
    "name": "conf.json",
    "lang": "json",
    "description": "Complete conf.json with UploadTest and DownloadTest configuration",
    "content": "{\n\t\"ProgressBar\": true,\n\t\"Log\": true,\n\t\"CSV\": false,\n\t\"RandomScan\": true,\n\t\"Hostname\": \"cp.cloudflare.com\",\n\t\"Ports\": [],\n\t\"Path\": \"/\",\n\t\"Headers\": {\n\t\t\"User-Agent\": [\"Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:153.0) Gecko/20100101 Firefox/153.0\"]\n\t},\n\t\"ResponseHeader\": {\n\t\t\"Server\": \"cloudflare\"\n\t},\n\t\"ResponseStatusCode\": [200, 204],\n\t\"Padding\": true,\n\t\"PaddingSize\": \"100-1000\",\n\t\"Ping\": {\n\t\t\"Enable\": true,\n\t\t\"MaxPing\": 300,\n\t\t\"Privileged\": true,\n\t\t\"Size\": \"24-65\"\n\t},\n\t\"Goroutines\": 16,\n\t\"Maxlatency\": 2000,\n\t\"Jitter\": {\n\t\t\"Enable\": true,\n\t\t\"MaxJitter\": 50.0,\n\t\t\"Samples\": 5,\n\t\t\"Interval\": 200\n\t},\n\t\"IpVersion\": 4,\n\t\"IplistPath\": \"ipv4.txt\",\n\t\"IgnoreRange\": [],\n\t\"AllowRange\": [],\n\t\"TLS\": {\n\t\t\"Enable\": true,\n\t\t\"SNI\": \"cp.cloudflare.com\",\n\t\t\"Insecure\": false,\n\t\t\"Alpn\": [\"h2\", \"http/1.1\"],\n\t\t\"Utls\": {\n\t\t\t\"Enable\": true,\n\t\t\t\"Fingerprint\": \"chrome\",\n\t\t\t\"TcpTimeout\": 1000,\n\t\t\t\"TcpConnectAttempt\": 1,\n\t\t\t\"Fragment\": {\n\t\t\t\t\"Enable\": false,\n\t\t\t\t\"Length\": \"50-100\",\n\t\t\t\t\"Delay\": \"10-15\",\n\t\t\t\t\"MaxSplit\": null\n\t\t\t}\n\t\t}\n\t},\n\t\"HTTP/3\": false,\n\t\"Noises\": {\n\t\t\"Enable\": false,\n\t\t\"Packets\": [\n\t\t\t{\n\t\t\t\t\"Type\": \"rand\",\n\t\t\t\t\"Payload\": \"1-10\",\n\t\t\t\t\"Sleep\": \"20-50\"\n\t\t\t},\n\t\t\t{\n\t\t\t\t\"Type\": \"rand\",\n\t\t\t\t\"Payload\": \"1-20\",\n\t\t\t\t\"Sleep\": \"20-50\"\n\t\t\t}\n\t\t]\n\t},\n\t\"DomainScan\": {\n\t\t\"Enable\": false,\n\t\t\"DomainAsSNI\": false,\n\t\t\"DomainAsHost\": false,\n\t\t\"Shuffle\": true,\n\t\t\"SkipIPV6\": true,\n\t\t\"DomainListPath\": \"cloudfalare-domains.txt\"\n\t},\n\t\"DownloadTest\": {\n\t\t\"Enable\": false,\n\t\t\"SeparateConnection\": false,\n\t\t\"Url\": \"https://speed.cloudflare.com/__down?bytes=10000000\",\n\t\t\"SNI\": \"cp.cloudflare.com\",\n\t\t\"TargetBytes\": 5000000,\n\t\t\"Timeout\": 5000\n\t},\n\t\"UploadTest\": {\n\t\t\"Enable\": false,\n\t\t\"SeparateConnection\": false,\n\t\t\"Url\": \"https://speed.cloudflare.com/__up\",\n\t\t\"SNI\": \"cp.cloudflare.com\",\n\t\t\"PayloadBytes\": 10000000,\n\t\t\"TargetBytes\": 5000000,\n\t\t\"Timeout\": 5000\n\t}\n}\n"
  }
